{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "Ensure no IAM policies documents allow '*' as a statement's resource for restrictable actions",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The policy allows unrestricted access to the 'sagemaker:CreatePresignedNotebookInstanceUrl' and 'sagemaker:ListNotebookInstances' actions by specifying '*' as the resource. This can lead to privilege escalation or unintended access."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "Ensure IAM policies do not allow write access without constraints",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The 'sagemaker:CreatePresignedNotebookInstanceUrl' action is a write operation and is allowed without resource constraints. This increases the risk of privilege escalation or misuse."
    }
  ],
  "patched_code": "resource \"aws_iam_policy\" \"privesc-sageMakerCreatePresignedNotebookURL-policy\" {\n  name        = \"privesc-sageMakerCreatePresignedNotebookURL-policy\"\n  path        = \"/\"\n  description = \"Allows privesc via sagemakerCreatePresignedNotebookURL\"\n  policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Effect   = \"Allow\"\n        Action = [\n          \"sagemaker:CreatePresignedNotebookInstanceUrl\",\n          \"sagemaker:ListNotebookInstances\"\n        ]\n        Resource = [\n          \"arn:aws:sagemaker:us-east-1:123456789012:notebook-instance/example-notebook-instance\"\n        ]\n      },\n    ]\n  })\n}",
  "fix_summary": "Restricted the 'Resource' field to a specific ARN for the notebook instance instead of using '*'. This mitigates the risk of privilege escalation and ensures write operations are constrained to a specific resource."
}
